namespace ghidra.framework.plugintool;



using ghidra.framework.plugintool.annotation;
using ghidra.framework.plugintool.util;
using ghidra.util;

public interface AutoService {
	public interface Wiring {
		void dispose();
	}

	static class WiringImpl : Wiring {
		/* @SuppressWarnings("unused") */ // strong reference
		private AutoServiceListener<object> listener;

		public WiringImpl(AutoServiceListener<object> listener) {
			this.listener = listener;
		}

		/* @Override */
		public void dispose() {
			this.listener = null;
		}
	}

	public static Wiring wireServicesProvidedAndConsumed(Plugin plugin) {
		registerServicesProvided(plugin, plugin.GetType(), plugin);
		return wireServicesConsumed(plugin, plugin);
	}

	/* @SuppressWarnings({ "unchecked", "rawtypes" }) */
	static void registerServicesProvided(Plugin plugin, Class<object> cls, object provider) {
		Class<object> superclass = cls.getSuperclass();
		if (superclass != null) {
			registerServicesProvided(plugin, superclass, provider);
		}
		foreach (Field f in cls.getDeclaredFields()) {
			AutoServiceProvided annotation = f.getAnnotation(typeof(AutoServiceProvided));
			if (annotation == null) {
				continue;
			}
			Class<object> iface = annotation.iface();
			Class<object> type = f.getType();
			if (!iface.isAssignableFrom(type)) {
				Msg.error(typeof(AutoService),
					type + " does not implement service interface " + iface);
				continue;
			}
			bool wasAccessible = f.isAccessible();
			f.setAccessible(true);
			try {
				plugin.registerServiceProvided((Class) iface, f.get(provider));
			}
			catch (Exception e) when (e is IllegalArgumentException or IllegalAccessException) {
				throw new AssertionError(e);
			}
			f.setAccessible(wasAccessible);
		}
	}

	public static Wiring wireServicesConsumed(PluginTool tool, object receiver) {
		AutoServiceListener<object> listener = new(receiver);
		tool.addServiceListener(listener);
		listener.notifyCurrentServices(tool);

		return new WiringImpl(listener);
	}

	public static Wiring wireServicesConsumed(Plugin plugin, object receiver) {
		// TODO: Validate against PluginInfo?
		return wireServicesConsumed(plugin.getTool(), receiver);
	}
}
